// Manages a pointer to a CDC whether generated by window or the app.


#pragma once
#include "Point.h"


class CDCex {

CDC*  dc{0};
CSize sz;
bool  attached{false};

public:

  CDCex() { }
 ~CDCex();

  CDC*   operator() ()        {return dc;}

  CDC*   operator= (CDC* cdc) {return dc = cdc;}

  bool   attach(HDC hdc);           // Used for printing only
  int    setMapMode(int mode)           {return dc ? dc->SetMapMode(mode)           : mode;}

  bool   getMetrics(TEXTMETRIC& metrics){return dc ? dc->GetTextMetrics(&metrics)   : false;}
  CSize  getExtent(TCchar* txt, int n)  {return dc ? dc->GetOutputTextExtent(txt, n): sz;}
  CSize  getExtent(Cstring txt)         {return dc ? dc->GetOutputTextExtent(txt)   : sz;}

  CFont* selectObj(CFont* font)         {return dc ? dc->SelectObject(font)         : 0;}
  CPen * selectObj(CPen*  pen)          {return dc ? dc->SelectObject(pen)          : 0;}

  bool   startDoc(TCchar* docName)      {return dc ? dc->StartDoc(docName) >  0     : false;}
  bool   endDoc()                       {return dc ? dc->EndDoc()          >= 0     : false;}
  bool   abortDoc()                     {return dc ? dc->AbortDoc()        >= 0     : false;}
  bool   startPage()                    {return dc ? dc->StartPage()       >= 0     : false;}
  bool   endPage()                      {return dc ? dc->EndPage()         >= 0     : false;}

  bool   textOut(int x, int y, TCchar* txt, int n)
                                        {return dc ? dc->TextOut(x, y, txt, n)      : false;}
  bool   textOut(int x, int y, Cstring txt)
                                        {return dc ? dc->TextOut(x, y, txt)         : false;}

  bool   polyLine(Point* points, int n) {return dc ? dc->Polyline(points, n)        : false;}

  // point size scaled up from 72 px/in
  int    scaleX( int v)      {return dc ? MulDiv(v, dc->GetDeviceCaps(LOGPIXELSX),  72) : 1;}
  int    scaleY( int v)      {return dc ? MulDiv(v, dc->GetDeviceCaps(LOGPIXELSY),  72) : 1;}
  // scale tenths of point from 720 px/10 inches
  int    scaleYY(int t)      {return dc ? MulDiv(t, dc->GetDeviceCaps(LOGPIXELSY), 720) : 1;}

  // Using the actual dimension in pixels and milimeters find the corresponding inches in pixels

  int    xActualPixels(double inches);
  int    yActualPixels(double inches);

  CFont* getCurrentFont() {return dc ? dc->GetCurrentFont() : 0;}
  };


extern CDCex displayDC;
extern CDCex printerDC;




